// Local XY origin is the middle of every cell. +Y is the character's front.
// Positive facing angles turn towards screen-right.
const GuildStacks = (() => {
  "use strict";
  const characters = {
    shusai: ["シュウサイ", 32], yuria: ["ユーリア", 32], riina: ["リィナ", 32], yukina: ["ユキナ", 32],
    jobava: ["ジョバヴァ", 32], tanaka: ["タナカ", 32], shiina: ["シイナ", 32], goto: ["ゴトウ", 32],
    mina: ["ミナ", 32], shion: ["シオン", 32], gald: ["ガルド", 32],
    toto: ["トト", 32], popo: ["ポポ", 32], boar: ["苔イノシシ", 24]
  };
  const models = new Map();
  const cell = 32, depth = .52;
  const pivot = 24, ground = 39;

  function model(id, url) {
    if (models.has(id)) return models.get(id);
    const layers = Array.from({ length: characters[id]?.[1] ?? 32 }, (_, z) => {
      const image = new Image();
      image.src = url(`stack_${id}/${String(z).padStart(2, "0")}`);
      return image;
    });
    const stamp = document.createElement("canvas");
    stamp.width = 2 * pivot;
    stamp.height = ground + 12;
    const entry = { layers, stamp, ctx: stamp.getContext("2d"), angle: null };
    models.set(id, entry);
    return entry;
  }

  // Rotate every horizontal section around the same XY origin, then raise it by z.
  function projectLayer(ctx, c, s, x, y, z, density = 1) {
    ctx.setTransform(c*density, -s*depth*density, s*density, c*depth*density,
      x*density, (y-z)*density);
  }

  function sceneryStamp(sheet, {pivot,ground,width,height}) {
    const stamp = document.createElement("canvas");
    // Twice the native resolution keeps thin flagpoles visible on a foreshortened plane.
    stamp.width = width * 2;
    stamp.height = height * 2;
    const ink = stamp.getContext("2d");
    ink.imageSmoothingEnabled = false;
    const edge = sheet.naturalWidth / 8;
    const count = sheet.naturalHeight / edge * 8;
    const c = Math.SQRT1_2;
    for (let z = 0; z < count; z++) {
      // Fill the half-step between consecutive planes at this resolution.
      for (let half = 0; half < 2; half++) {
        projectLayer(ink, c, -c, pivot, ground, z + half/2, 2);
        ink.drawImage(sheet, z%8*edge, Math.floor(z/8)*edge, edge, edge,
          -edge/2, -edge/2, edge, edge);
      }
    }
    return stamp;
  }

  function draw(ctx, id, url, x, y, size, angle, pose = {}) {
    const m = model(id, url);
    if (m.angle !== angle) {
      if (m.angle === null && !m.layers.every(img => img.complete && img.naturalWidth)) return;
      // Project a rotated XY plane, then raise its origin one pixel per Z.
      const c = Math.cos(angle), s = Math.sin(angle);
      const ink = m.ctx;
      ink.setTransform(1, 0, 0, 1, 0, 0);
      ink.clearRect(0, 0, m.stamp.width, m.stamp.height);
      ink.imageSmoothingEnabled = false;
      for (let z = 0; z < m.layers.length; z++) {
        projectLayer(ink, c, s, pivot, ground, z);
        ink.drawImage(m.layers[z], -cell / 2, -cell / 2);
      }
      m.angle = angle;
    }

    const { bob = 0, tilt = 0, squat = 1 } = pose;
    ctx.fillStyle = "rgba(45,36,26,.22)";
    ctx.beginPath();
    ctx.ellipse(x, y, (id === "boar" ? 9 : 7) * size, 2.5 * size, 0, 0, 2 * Math.PI);
    ctx.fill();
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y - bob));
    ctx.scale(size, size * squat);
    ctx.rotate(tilt);
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(m.stamp, -pivot, -ground);
    ctx.restore();
  }

  async function preview(canvas, id, url) {
    const m = model(id,url);
    await Promise.all(m.layers.map(image => image.decode()));
    if (canvas.isConnected) draw(canvas.getContext("2d"),id,url,32,43,1,Math.PI/8);
  }

  function gallery(host, url) {
    const views = { auto: "自動回転", front: "正面", quarter: "斜め", back: "背面" };
    const angles = { front: 0, quarter: Math.PI / 4, back: Math.PI };
    const turn = Math.PI * 2 / 18000;
    host.innerHTML = `<header class="stack-heading"><h1>木もれびギルドの回転見本</h1>
      <div class="stack-angles" role="group" aria-label="表示する向き">${Object.entries(views)
        .map(([key, label]) => `<button type="button" class="btn" data-facing="${key}" aria-pressed="${key === "auto"}">${label}</button>`).join("")}</div></header>
      <div class="stack-grid">${Object.entries(characters).map(([id, [name, count]]) =>
        `<figure><canvas width="72" height="52" data-stack="${id}" aria-label="${name}の回転見本"></canvas>
        <figcaption><strong>${name}</strong><span>${count} 層</span></figcaption></figure>`).join("")}</div>`;
    const actors = Array.from(host.querySelectorAll("canvas"), canvas =>
      ({ id: canvas.dataset.stack, ctx: canvas.getContext("2d") }));
    let view = "auto", origin = performance.now(), angle = 0;
    host.addEventListener("click", event => {
      const button = event.target.closest("button[data-facing]");
      if (!button) return;
      view = button.dataset.facing;
      if (view === "auto") origin = performance.now() - angle / turn;
      else angle = angles[view];
      for (const b of host.querySelectorAll("button[data-facing]")) {
        b.setAttribute("aria-pressed", String(b === button));
      }
    });
    function paint(now) {
      if (view === "auto") angle = ((now - origin) * turn) % (2 * Math.PI);
      for (const { id, ctx } of actors) {
        ctx.clearRect(0, 0, 72, 52);
        draw(ctx, id, url, 36, 43, 1, angle);
      }
      requestAnimationFrame(paint);
    }
    requestAnimationFrame(paint);
  }

  return { draw, preview, gallery, sceneryStamp };
})();

